description:
A tool supports telemetry major version `toolMajor` and knows minor versions up to `toolMinor`. A game publishes a header with its `major`, `minor` and `size` (bytes). Write `check(toolMajor, toolMinor, gameMajor, gameMinor)`:

- different major versions: `Incompatible`;
- same major, game minor higher than the tool's: `NewerGame` (works; the tool ignores fields it does not know);
- same major, game minor lower than the tool's: `OlderGame` (works; some fields will be missing);
- otherwise `Exact`.

Then `fieldAvailable(gameSize, offset, size)`: true if a field at `offset` of `size` bytes lies entirely within the game's struct size. Guard against overflow in `offset + size`.

starter.solution.cpp:
#include <cstdint>

enum class Compat { Exact, NewerGame, OlderGame, Incompatible };

Compat check(int toolMajor, int toolMinor, int gameMajor, int gameMinor)
{
    return Compat::Exact;
}

bool fieldAvailable(std::uint32_t gameSize, std::uint32_t offset, std::uint32_t size)
{
    return true;
}

solution.solution.cpp:
#include <cstdint>

enum class Compat { Exact, NewerGame, OlderGame, Incompatible };

Compat check(int toolMajor, int toolMinor, int gameMajor, int gameMinor)
{
    if (toolMajor != gameMajor) return Compat::Incompatible;
    if (gameMinor > toolMinor) return Compat::NewerGame;
    if (gameMinor < toolMinor) return Compat::OlderGame;
    return Compat::Exact;
}

bool fieldAvailable(std::uint32_t gameSize, std::uint32_t offset, std::uint32_t size)
{
    return offset <= gameSize && size <= gameSize - offset;      // no overflow possible
}

unitTests:
TEST("same version") { CHECK(check(1, 2, 1, 2) == Compat::Exact); }
TEST("newer game") { CHECK(check(1, 2, 1, 5) == Compat::NewerGame); }
TEST("older game") { CHECK(check(1, 2, 1, 0) == Compat::OlderGame); }
TEST("different majors") { CHECK(check(1, 2, 2, 0) == Compat::Incompatible); CHECK(check(2, 0, 1, 9) == Compat::Incompatible); }
TEST("fields inside the size") { CHECK(fieldAvailable(48, 0, 4)); CHECK(fieldAvailable(48, 44, 4)); }
TEST("fields past the size") { CHECK(!fieldAvailable(48, 48, 4)); CHECK(!fieldAvailable(48, 46, 4)); }
TEST("no overflow") { CHECK(!fieldAvailable(48, 0xFFFFFFF0u, 0x20u)); }
TEST("zero-size field at the end") { CHECK(fieldAvailable(48, 48, 0)); }

